-- CarworX staging DEMO businesses. SYNTHETIC DATA ONLY.
--
-- Twelve clearly fictional businesses across Gauteng and the Western Cape, so
-- staging search, category and listing pages have something to show. Every
-- name ends in "(DEMO)", every description starts "DEMO listing", every
-- address is a made-up "Demo"/"Example"/"Sample" street and every
-- provenance reference starts "demo-seed-", in the same way as the
-- "Synthetic ..." fixtures in seed.sql (ca7c1000-...). Coordinates are
-- suburb centres, not real premises.
--
-- Not loaded by `supabase db reset` (config.toml seeds only seed.sql), so the
-- test suites see the same fixtures as before. Apply by hand AFTER seed.sql
-- (it reuses the synthetic admin 5eed...0004 as the verifier):
--   psql "$DB_URL" -v ON_ERROR_STOP=1 -f supabase/seed-demo.sql
-- Idempotent: it removes its own rows first. Remove with seed-demo-remove.sql.
begin;

-- Remove any earlier copy (children first). Only DEMO ids (de3...) match.
delete from public.verifications where organisation_id::text like 'de300000-%';
delete from public.listing_hours where organisation_id::text like 'de300000-%';
delete from public.listing_services where organisation_id::text like 'de300000-%';
delete from public.service_areas where organisation_id::text like 'de300000-%';
delete from public.listings where organisation_id::text like 'de300000-%';
delete from public.branches where organisation_id::text like 'de300000-%';
delete from public.coordinate_sources where organisation_id::text like 'de300000-%';
delete from public.organisations where id::text like 'de300000-%';









-- Readable service names for the demo. seed.sql names them "Synthetic ...";
-- only rows still carrying that name change, and seed-demo-remove.sql puts
-- them back.
update public.services s set name = v.name
from (values ('wash','Wash & valet'),('service','Mechanical service'),('tyres','Tyres & alignment'),
 ('paint','Panel & paint'),('electrical','Auto electrical'),('mobile-repair','Mobile mechanic'),
 ('glass','Windscreen & glass')) v(slug, name)
where s.slug = v.slug and s.name like 'Synthetic %';

commit;
